const cfg = $input.item.json;
const what = (cfg.keywords || []).join(" ");
const where = cfg.location || "";
const maxPages = cfg.max_pages || 3;
const out = [];
for (let p = 1; p <= maxPages; p++) {
  out.push({ json: { what: what, where: where, results_per_page: 50, page: p, country: "gb" } });
}
return out;

const items = $input.all();
const out = [];
let anySuccess = false;
for (const item of items) {
  const resp = item.json;
  if (!resp || resp.error || !Array.isArray(resp.results)) { continue; }
  anySuccess = true;
  for (const r of resp.results) {
    out.push({
      schema_version: "1.0",
      job_id: "adzuna_" + r.id,
      job_title: r.title || null,
      company: (r.company && r.company.display_name) || null,
      location: (r.location && r.location.display_name) || null,
      source: "adzuna",
      description: r.description || "",
      application_url: r.redirect_url || null,
      required_skills: [],
      retrieved_at: new Date().toISOString(),
      employment_type: r.contract_time || null,
      salary: (r.salary_min || r.salary_max) ? { min: r.salary_min || null, max: r.salary_max || null } : null
    });
  }
}
return [{ json: { source: "adzuna", status: anySuccess ? "ok" : "unavailable", jobs: out, pages_fetched: items.length } }];

function stripHtml(html) { return (html || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(); }
const resp = $input.item.json;
const out = [];
if (!resp || resp.error || !Array.isArray(resp.jobs)) {
