  });
}
return [{ json: { source: "remotive", status: "ok", jobs: out } }];

const items = $input.all();
let jobs = [];
const sourceStatus = [];
for (const item of items) {
  if (item.json.jobs) { jobs = jobs.concat(item.json.jobs); }
  sourceStatus.push({ source: item.json.source, status: item.json.status });
}
return [{ json: { jobs: jobs, source_status: sourceStatus } }];

const SKILL_DICT = ["python","javascript","typescript","react","node.js","django","flask","postgresql","postgres","mysql","docker","kubernetes","aws","gcp","azure","sql","java","c++","c#","go","rust","rest api","graphql","ci/cd","git","terraform"];
const SENIORITY_MAP = { "senior": "senior", "sr.": "senior", "junior": "junior", "jr.": "junior", "lead": "lead", "principal": "principal", "staff": "staff" };
function mine(job) {
  const lower = ((job.description || "") + " " + (job.job_title || "")).toLowerCase();
  const required = SKILL_DICT.filter(function(s) { return lower.indexOf(s) !== -1; });
  const expMatch = lower.match(/(\d{1,2})\+?\s*(?:years|yrs)\s*(?:of)?\s*experience/);
  const eduMatch = lower.match(/\b(bachelor|master|phd|b\.?s\.?|m\.?s\.?)\b/);
  const seniorityKey = Object.keys(SENIORITY_MAP).filter(function(k) { return lower.indexOf(k) !== -1; })[0];
  const out = Object.assign({}, job);
  out.required_skills = required.length ? required : (job.required_skills || []);
  out.preferred_skills = job.preferred_skills || [];
  out.required_experience_years = expMatch ? parseInt(expMatch[1]) : (job.required_experience_years != null ? job.required_experience_years : null);
  out.education_requirement = eduMatch ? eduMatch[1] : (job.education_requirement != null ? job.education_requirement : null);
  out.seniority_level = seniorityKey ? SENIORITY_MAP[seniorityKey] : (job.seniority_level != null ? job.seniority_level : null);
  out.technologies = (job.technologies && job.technologies.length) ? job.technologies : required;
  return out;
}
const input = $input.item.json;
const mined = (input.jobs || []).map(mine);
return [{ json: { jobs: mined, source_status: input.source_status } }];

function normCompany(c) { return (c || "").toLowerCase().replace(/\b(inc|llc|ltd|gmbh|corp)\b\.?/g, "").trim(); }
function normTitle(t) { return (t || "").toLowerCase().replace(/[^a-z0-9 ]/g, "").trim(); }
function jaccard(a, b) {
  const sa = {}; a.split(" ").filter(Boolean).forEach(function(w) { sa[w] = true; });
  const sb = {}; b.split(" ").filter(Boolean).forEach(function(w) { sb[w] = true; });
  const union = {}; Object.keys(sa).forEach(function(w) { union[w] = true; }); Object.keys(sb).forEach(function(w) { union[w] = true; });
  let inter = 0; Object.keys(sa).forEach(function(w) { if (sb[w]) { inter++; } });
  const unionSize = Object.keys(union).length;
  return unionSize === 0 ? 0 : inter / unionSize;
}
const input = $input.item.json;
const jobs = input.jobs || [];
const kept = [];
const dropped_duplicates = [];
for (const job of jobs) {
  const nc = normCompany(job.company);
  const nt = normTitle(job.job_title);
  let dupIndex = -1;
  for (let i = 0; i < kept.length; i++) {
    const other = kept[i];
    const sameCompany = normCompany(other.company) === nc;
    const sim = jaccard(nt, normTitle(other.job_title));
    const locMatch = (other.location || "").toLowerCase() === (job.location || "").toLowerCase() || /remote/i.test(other.location || "") || /remote/i.test(job.location || "");
    if (sameCompany && sim >= 0.6 && locMatch) { dupIndex = i; break; }
  }
  if (dupIndex === -1) {
    kept.push(job);
  } else {
    if ((job.description || "").length > (kept[dupIndex].description || "").length) {
      dropped_duplicates.push(kept[dupIndex].job_id);
      kept[dupIndex] = job;
    } else {
      dropped_duplicates.push(job.job_id);
    }
  }
}
return [{ json: { jobs: kept, dropped_duplicates: dropped_duplicates, source_status: input.source_status } }];

const input = $input.item.json;
const jobs = input.jobs || [];
const reasons = { empty_description: 0, missing_title_or_company: 0, invalid_url: 0 };
const kept = [];
for (const job of jobs) {
  if (!job.description || !job.description.trim()) { reasons.empty_description++; continue; }
  if (!job.job_title || !job.company) { reasons.missing_title_or_company++; continue; }
  if (!job.application_url || !/^https?:\/\//.test(job.application_url)) { reasons.invalid_url++; continue; }
  kept.push(job);
}
return [{ json: { jobs: kept, dropped_count: jobs.length - kept.length, dropped_reasons: reasons, source_status: input.source_status } }];
